<?php
// Checkout and order summary.

    $items = [];
    if ($route === 'rinciannow') foreach (($_SESSION['buy_now'] ?? []) as $pid=>$qty) { $row=one('SELECT * FROM tb_barang WHERE id_barang=?',[(int)$pid]); if ($row) { $row['qty']=$qty; $items[]=$row; } }
    else foreach (query('SELECT b.*, SUM(k.qty) AS qty FROM keranjang k JOIN tb_barang b ON b.id_barang=k.id_barang WHERE k.id_user=? GROUP BY b.id_barang',[$userId]) as $row) if (in_array((int)$row['id_barang'],$_SESSION['selected_cart_items']??[],true)) $items[]=$row;
    page_title('CHECKOUT', 'Hampir menjadi milik Anda.', 'Lengkapi alamat, pilih pengiriman, lalu buat pesanan.');
    if (!$items) empty_state('Belum ada produk dipilih', 'Pilih produk dari keranjang sebelum checkout.', 'pages/keranjang.php','Kembali ke keranjang');
    else { $subtotal=0; $discount=0; $promoLabels=[];
        foreach ($items as &$checkoutItem) {
            $offer=product_offer($checkoutItem); $checkoutItem['offer']=$offer;
            $subtotal += $offer['original']*$checkoutItem['qty'];
            $discount += $offer['discount']*$checkoutItem['qty'];
            if ($offer['label'] !== '') $promoLabels[]=$offer['label'];
        } unset($checkoutItem); ?>
    <form method="post" class="checkout-layout"><?= csrf() ?><div class="form-stack"><section class="panel"><h2><span class="step">01</span> Alamat penerima</h2><?php field('Nama penerima','nama',input('nama',$user['nama']),'text','required maxlength="99"'); field('Nomor telepon','telp',input('telp',$user['telp']),'tel','required maxlength="20"'); field('Alamat lengkap','alamat',input('alamat',$user['alamat']),'text','required maxlength="99"'); ?></section><section class="panel"><h2><span class="step">02</span> Pengiriman & pembayaran</h2><label class="field"><span>Jasa pengiriman</span><select name="jasa_kirim" required data-checkout-cost><option value="" data-cost="0">Pilih jasa pengiriman</option><?php foreach(query('SELECT * FROM jasa_kirim') as $j): ?><option value="<?= (int)$j['id_jasa'] ?>" data-cost="<?= (int)$j['harga_jasa'] ?>" <?= input('jasa_kirim')==(string)$j['id_jasa']?'selected':'' ?>><?= e($j['nama_jasa']) ?> · <?= rupiah($j['harga_jasa']) ?></option><?php endforeach; ?></select></label><label class="field"><span>Metode pembayaran</span><select name="metode" required data-checkout-cost><option value="" data-cost="0">Pilih metode pembayaran</option><?php foreach(query('SELECT * FROM metode') as $m): ?><option value="<?= (int)$m['id_metode'] ?>" data-cost="<?= (int)$m['harga_admin'] ?>" <?= input('metode')==(string)$m['id_metode']?'selected':'' ?>><?= e($m['nama_metode']) ?> · biaya <?= rupiah($m['harga_admin']) ?></option><?php endforeach; ?></select></label><?php field('Catatan pesanan (opsional)','pesan',input('pesan'),'text','maxlength="255"'); ?></section></div><aside class="panel summary"><h2>Pesanan Anda</h2><?php foreach($items as $item): ?><div class="mini-product"><img src="<?= e(url($item['img'])) ?>" alt=""><div><strong><?= e($item['nama_barang']) ?></strong><small><?= (int)$item['qty'] ?> × <?= rupiah($item['offer']['price']) ?></small><?php if ($item['offer']['discount']): ?><small class="discount-value"><?= e($item['offer']['label']) ?> &middot; hemat <?= rupiah($item['offer']['discount']*$item['qty']) ?></small><?php endif; ?></div></div><?php endforeach; ?><div class="summary-line"><span>Subtotal produk</span><strong><?= rupiah($subtotal) ?></strong></div><div class="summary-line"><span>Pengiriman</span><strong data-shipping-total>Pilih kurir</strong></div><div class="summary-line"><span>Biaya pembayaran</span><strong data-payment-fee>Pilih metode</strong></div><div class="summary-line"><span>Diskon promo</span><strong class="discount-value">- <?= rupiah($discount) ?></strong></div><p class="promo-caption"><?= $discount ? e(implode(', ',array_unique($promoLabels))) : 'Belum ada promo aktif untuk produk yang dipilih.' ?></p><div class="summary-line total"><span>Total pembayaran</span><strong data-checkout-total="<?= $subtotal ?>" data-discount="<?= $discount ?>"><?= rupiah($subtotal-$discount) ?></strong></div><button class="button wide">Buat pesanan <?= icon('arrow') ?></button><p class="muted small-text">Harga dan ketersediaan stok diperiksa kembali saat pesanan dibuat.</p></aside></form>
    <?php }
